package zw.ac.uz.dpdms.auth; import org.springframework.context.annotation.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.boot.CommandLineRunner;
@Configuration public class AuthConfiguration {@Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean CommandLineRunner seed(UserRepository users,PasswordEncoder encoder){return a->{if(users.findByUsername("national@dpdms.local").isEmpty()){AppUser u=new AppUser();u.username="national@dpdms.local";u.passwordHash=encoder.encode("ChangeMe123!");u.role="NATIONAL";u.hazard="";u.ward="";users.save(u);}};}}
